async function handleSuperAdminBiometricFirmwareApi(request, response) {
  if (!requireSuperAdmin(request, response)) {
    return;
  }
  if (!biometricFirmwareCompile) {
    sendJson(response, 503, {
      message: "Firmware compile service is unavailable on this server.",
    });
    return;
  }

  try {
    if (request.method === "GET") {
      const requestUrl = new URL(request.url, `http://127.0.0.1:${PORT}`);
      const flashId = String(requestUrl.searchParams.get("flashId") || "").trim();
      const fileName = String(requestUrl.searchParams.get("name") || "").trim();
      if (flashId || fileName) {
        const artifactPath = biometricFirmwareCompile.getFlashArtifactPath?.(flashId, fileName);
        if (!artifactPath) {
          sendJson(response, 404, { message: "Firmware flash artifact was not found. Build again, then flash." });
          return;
        }
        const data = fs.readFileSync(artifactPath);
        setCorsHeaders(response);
        response.writeHead(200, {
          "Content-Type": "application/octet-stream",
          "Content-Length": data.length,
          "Cache-Control": "no-store",
        });
        response.end(data);
        return;
      }
      sendJson(response, 200, {
        ok: true,
        status: await biometricFirmwareCompile.getBiometricFirmwareToolingStatus(),
      });
      return;
    }

    if (request.method !== "POST") {
      sendJson(response, 405, { message: "Method not allowed." });
      return;
    }

    const payload = await parseRequestBody(request);
    const source = String(payload?.source ?? "repo").trim().toLowerCase();
    let compiled = null;
    if (source === "upload") {
      compiled = await biometricFirmwareCompile.compileBiometricFirmwareFromSketchText(payload?.sketch);
    } else {
      compiled = await biometricFirmwareCompile.compileBiometricFirmwareFromRepo();
    }

    sendJson(response, 200, {
      ok: true,
      message: "Firmware compiled. Flash ESP32 to upload the built binaries.",
      fqbn: compiled.fqbn,
      source: compiled.source,
      protocolVersion: compiled.protocolVersion,
      sketchHash: compiled.sketchHash,
      flashId: compiled.flashId,
      files: compiled.files,
    });
  } catch (error) {
    sendJson(response, 400, {
      ok: false,
      message: error instanceof Error
        ? error.message
        : "Unable to compile biometric firmware.",
    });
  }
}
